1	//! HTTP proxy logic
2	//!
3	//! Receives inbound requests, strips hop-by-hop headers, delegates auth to the
4	//! provider, and forwards to the upstream URL. Returns the upstream response
5	//! verbatim (including error status codes from upstream).
6	
7	use axum::http::StatusCode;
8	use axum::response::{IntoResponse, Response};
9	use bytes::Bytes;
10	use futures_util::Stream;
11	use provider::Provider;
12	use std::pin::Pin;
13	use std::sync::Arc;
14	use std::task::{Context, Poll};
15	use std::time::{Duration, Instant};
16	use tokio::time::Sleep;
17	use tracing::{error, info, instrument, warn};
18	
19	/// Maximum retry attempts for upstream timeouts (spec: 2 retries = 3 total attempts)
20	const MAX_UPSTREAM_ATTEMPTS: u32 = 3;
21	
22	/// Fixed backoff between upstream timeout retries (spec: 100ms)
23	const UPSTREAM_RETRY_DELAY: Duration = Duration::from_millis(100);
24	
25	/// Maximum request body size (spec: 10 MiB)
26	pub const MAX_BODY_SIZE: usize = 10 * 1024 * 1024;
27	
28	/// Headers to strip before forwarding (hop-by-hop per RFC 2616 Section 13.5.1)
29	const HOP_BY_HOP_HEADERS: &[&str] = &[
30	    "connection",
31	    "keep-alive",
32	    "proxy-authenticate",
33	    "proxy-authorization",
34	    "te",
35	    "trailer",
36	    "transfer-encoding",
37	    "upgrade",
38	];
39	
40	/// Shared state passed to the proxy handler via axum State extractor
41	#[derive(Clone)]
42	pub struct ProxyState {
43	    pub client: reqwest::Client,
44	    pub upstream_url: String,
45	    pub provider: Arc<dyn Provider>,
46	    pub timeout: Duration,
47	    pub requests_total: Arc<std::sync::atomic::AtomicU64>,
48	    pub errors_total: Arc<std::sync::atomic::AtomicU64>,
49	    pub in_flight: Arc<std::sync::atomic::AtomicU64>,
50	    /// Maximum failover attempts for quota exhaustion. Equals pool size in OAuth
51	    /// mode (each attempt uses a different account). Set to 1 in passthrough mode
52	    /// (no failover, just forward the error).
53	    pub max_failover_attempts: usize,
54	}
55	
56	/// RAII guard that decrements the in-flight counter when dropped, ensuring the
57	/// counter stays accurate even if the handler returns early or panics.
58	struct InFlightGuard(Arc<std::sync::atomic::AtomicU64>);
59	
60	impl Drop for InFlightGuard {
61	    fn drop(&mut self) {
62	        self.0.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
63	    }
64	}
65	
66	// Wraps a byte stream with an idle timeout that resets on each received chunk.
67	// If no data arrives within the timeout window, the stream terminates cleanly
68	// (returns None). This protects against dead upstream connections mid-stream
69	// without killing healthy long-running SSE streams that send periodic data.
70	pin_project_lite::pin_project! {
71	    struct IdleTimeoutStream<S> {
72	        #[pin]
73	        inner: S,
74	        #[pin]
75	        deadline: Sleep,
76	        timeout: Duration,
77	        timed_out: bool,
78	    }
79	}
80	
81	impl<S> IdleTimeoutStream<S> {
82	    fn new(inner: S, timeout: Duration) -> Self {
83	        Self {
84	            inner,
85	            deadline: tokio::time::sleep(timeout),
86	            timeout,
87	            timed_out: false,
88	        }
89	    }
90	}
91	
92	impl<S, E> Stream for IdleTimeoutStream<S>
93	where
94	    S: Stream<Item = Result<Bytes, E>>,
95	    E: Into<Box<dyn std::error::Error + Send + Sync>>,
96	{
97	    type Item = Result<Bytes, Box<dyn std::error::Error + Send + Sync>>;
98	
99	    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
100	        let mut this = self.project();
101	
102	        if *this.timed_out {
103	            return Poll::Ready(None);
104	        }
105	
106	        if this.deadline.as_mut().poll(cx).is_ready() {
107	            *this.timed_out = true;
108	            warn!("upstream idle timeout after {}s", this.timeout.as_secs());
109	            return Poll::Ready(None);
110	        }
111	
112	        match this.inner.poll_next(cx) {
113	            Poll::Ready(Some(Ok(bytes))) => {
114	                this.deadline
115	                    .reset(tokio::time::Instant::now() + *this.timeout);
116	                Poll::Ready(Some(Ok(bytes)))
117	            }
118	            Poll::Ready(Some(Err(e))) => Poll::Ready(Some(Err(e.into()))),
119	            Poll::Ready(None) => Poll::Ready(None),
120	            Poll::Pending => Poll::Pending,
121	        }
122	    }
123	}
124	
125	/// JSON error response per spec: {"error":{"type":"proxy_error","message":"...","request_id":"req_..."}}
126	fn error_response(status: StatusCode, message: &str, request_id: &str) -> Response {
127	    let body = serde_json::json!({
128	        "error": {
129	            "type": "proxy_error",
130	            "message": message,
131	            "request_id": request_id,
132	        }
133	    });
134	    (
135	        status,
136	        [(axum::http::header::CONTENT_TYPE, "application/json")],
137	        body.to_string(),
138	    )
139	        .into_response()
140	}
141	
142	/// Proxy an inbound request to upstream with header injection, retries, and failover.
143	///
144	/// Retry strategy per spec: UpstreamTimeout gets 2 retries with 100ms fixed backoff.
145	/// Failover strategy: QuotaExceeded triggers account switch and re-send; Permanent
146	/// errors disable the account and return the error; Transient errors are returned.
147	#[instrument(skip_all, fields(request_id = %request_id, method = %request.method(), path = %request.uri().path()))]
148	pub async fn proxy_request(
149	    state: &ProxyState,
150	    request: axum::http::Request<axum::body::Body>,
151	    request_id: String,
152	) -> Response {
153	    let start = Instant::now();
154	    state
155	        .requests_total
156	        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
157	    state
158	        .in_flight
159	        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
160	    let _in_flight_guard = InFlightGuard(state.in_flight.clone());
161	
162	    let method = request.method().clone();
163	    let method_str = method.to_string();
164	    let uri = request.uri().clone();
165	
166	    // Build the upstream URL by appending the request path and query
167	    let upstream_url = if let Some(pq) = uri.path_and_query() {
168	        format!("{}{}", state.upstream_url.trim_end_matches('/'), pq)
169	    } else {
170	        state.upstream_url.clone()
171	    };
172	
173	    // Collect original request headers, stripping hop-by-hop, host, and
174	    // content-length. Host carries the proxy's hostname — reqwest sets the
175	    // correct one from the upstream URL. Content-Length must be recalculated
176	    // by reqwest/hyper because OAuth mode re-serializes the body (system
177	    // prompt injection changes byte count). Forwarding the client's original
178	    // Content-Length causes a mismatch that Cloudflare rejects with 400.
179	    //
180	    // Uses append() instead of insert() to preserve multi-value headers
181	    // (e.g. multiple Cookie or Accept-Encoding values from the client).
182	    let mut original_headers = reqwest::header::HeaderMap::new();
183	    for (name, value) in request.headers() {
184	        if !is_hop_by_hop(name.as_str())
185	            && name != axum::http::header::HOST
186	            && name != axum::http::header::CONTENT_LENGTH
187	        {
188	            original_headers.append(name.clone(), value.clone());
189	        }
190	    }
191	
192	    // Read the request body
193	    let body_bytes = match axum::body::to_bytes(request.into_body(), MAX_BODY_SIZE).await {
194	        Ok(b) => b,
195	        Err(e) => {
196	            state
197	                .errors_total
198	                .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
199	            error!(error = %e, "failed to read request body");
200	            let status = StatusCode::BAD_REQUEST;
201	            crate::metrics::record_request(
202	                status.as_u16(),
203	                &method_str,
204	                start.elapsed().as_secs_f64(),
205	            );
206	            crate::metrics::record_upstream_error("invalid_request");
207	            return error_response(status, &format!("invalid request body: {e}"), &request_id);
208	        }
209	    };
210	
211	    // Parse body JSON once if the provider needs it (OAuth mode needs body for
212	    // system prompt injection). The parsed value is re-used across failover attempts.
213	    let parsed_body = if state.provider.needs_body() {
214	        match serde_json::from_slice::<serde_json::Value>(&body_bytes) {
215	            Ok(v) => Some(v),
216	            Err(e) => {
217	                state
218	                    .errors_total
219	                    .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
220	                let status = StatusCode::BAD_REQUEST;
221	                crate::metrics::record_request(
222	                    status.as_u16(),
223	                    &method_str,
224	                    start.elapsed().as_secs_f64(),
225	                );
226	                crate::metrics::record_upstream_error("invalid_request");
227	                return error_response(status, &format!("Invalid JSON body: {e}"), &request_id);
228	            }
229	        }
230	    } else {
231	        None
232	    };
233	
234	    // Maximum failover attempts equals the pool size (each attempt uses a
235	    // different account). Passthrough mode uses 1 attempt (no failover).
236	    let max_failovers = state.max_failover_attempts;
237	
238	    for failover in 0..max_failovers {
239	        // Start from original headers each attempt so provider injection is clean.
240	        // Without this, headers from a previous failed account (e.g. wrong Bearer
241	        // token) would carry over into the next attempt.
242	        let mut headers = original_headers.clone();
243	        let mut body_value = parsed_body.clone().unwrap_or(serde_json::Value::Null);
244	
245	        let account_id = match state
246	            .provider
247	            .prepare_request(&mut headers, &mut body_value)
248	            .await
249	        {
250	            Ok(id) => id,
251	            Err(e) => {
252	                state
253	                    .errors_total
254	                    .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
255	                let status = StatusCode::SERVICE_UNAVAILABLE;
256	                crate::metrics::record_request(
257	                    status.as_u16(),
258	                    &method_str,
259	                    start.elapsed().as_secs_f64(),
260	                );
261	                error!(error = %e, "provider prepare_request failed");
262	                return error_response(status, &format!("provider error: {e}"), &request_id);
263	            }
264	        };
265	
266	        let final_body = if state.provider.needs_body() {
267	            serde_json::to_vec(&body_value)
268	                .unwrap_or_else(|_| body_bytes.to_vec())
269	                .into()
270	        } else {
271	            body_bytes.clone()
272	        };
273	
274	        // Timeout retry loop within this failover attempt
275	        let mut last_error_response = None;
276	
277	        for attempt in 0..MAX_UPSTREAM_ATTEMPTS {
278	            if attempt > 0 {
279	                warn!(attempt, "retrying after upstream timeout");
280	                tokio::time::sleep(UPSTREAM_RETRY_DELAY).await;
281	            }
282	
283	            let req = state
284	                .client
285	                .request(method.clone(), &upstream_url)
286	                .headers(headers.clone())
287	                .body(final_body.clone());
288	
289	            let send_result = tokio::time::timeout(state.timeout, req.send()).await;
290	            match send_result {
291	                Ok(Ok(upstream_response)) => {
292	                    let status = upstream_response.status();
293	
294	                    // For error responses that may need classification (quota/auth
295	                    // errors), buffer the body. For success or non-classifiable
296	                    // errors, stream directly.
297	                    if status.is_client_error() || status.is_server_error() {
298	                        if let Some(ref acct) = account_id {
299	                            // Buffer error body for classification
300	                            let resp_headers = upstream_response.headers().clone();
301	                            let error_body = upstream_response.bytes().await.unwrap_or_default();
302	                            let error_body_str = String::from_utf8_lossy(&error_body).to_string();
303	
304	                            let classification = state
305	                                .provider
306	                                .classify_error(status.as_u16(), &error_body_str);
307	
308	                            match classification {
309	                                provider::ErrorClassification::QuotaExceeded => {
310	                                    warn!(
311	                                        account_id = acct,
312	                                        failover, "quota exhausted, failing over to next account"
313	                                    );
314	                                    let _ = state.provider.report_error(acct, classification).await;
315	                                    crate::metrics::record_upstream_error("quota_exhausted");
316	                                    crate::metrics::record_pool_quota_exhaustion(acct);
317	                                    crate::metrics::record_pool_failover(acct, "quota_exhausted");
318	                                    crate::metrics::record_pool_account_status(
319	                                        acct,
320	                                        "cooling_down",
321	                                    );
322	                                    // Store response in case this is the last failover
323	                                    last_error_response = Some((status, resp_headers, error_body));
324	                                    break; // exit timeout retry loop, continue failover loop
325	                                }
326	                                provider::ErrorClassification::Permanent => {
327	                                    warn!(account_id = acct, "permanent error, disabling account");
328	                                    let _ = state.provider.report_error(acct, classification).await;
329	                                    crate::metrics::record_upstream_error("permanent");
330	                                    crate::metrics::record_pool_account_status(acct, "disabled");
331	                                    // Return error to client immediately
332	                                    let elapsed = start.elapsed();
333	                                    crate::metrics::record_request(
334	                                        status.as_u16(),
335	                                        &method_str,
336	                                        elapsed.as_secs_f64(),
337	                                    );
338	                                    state
339	                                        .errors_total
340	                                        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
341	                                    return build_buffered_response(
342	                                        status,
343	                                        &resp_headers,
344	                                        error_body,
345	                                    );
346	                                }
347	                                provider::ErrorClassification::Transient => {
348	                                    // Return error to client (existing timeout retry
349	                                    // handles transport-level retries)
350	                                    let elapsed = start.elapsed();
351	                                    crate::metrics::record_request(
352	                                        status.as_u16(),
353	                                        &method_str,
354	                                        elapsed.as_secs_f64(),
355	                                    );
356	                                    info!(
357	                                        status = status.as_u16(),
358	                                        latency_ms = elapsed.as_millis() as u64,
359	                                        "request completed (transient error)"
360	                                    );
361	                                    return build_buffered_response(
362	                                        status,
363	                                        &resp_headers,
364	                                        error_body,
365	                                    );
366	                                }
367	                            }
368	                        } else {
369	                            // Passthrough mode: no account, stream error response directly
370	                            let resp_headers = upstream_response.headers().clone();
371	                            let elapsed = start.elapsed();
372	                            crate::metrics::record_request(
373	                                status.as_u16(),
374	                                &method_str,
375	                                elapsed.as_secs_f64(),
376	                            );
377	                            info!(
378	                                status = status.as_u16(),
379	                                latency_ms = elapsed.as_millis() as u64,
380	                                "request completed"
381	                            );
382	                            return build_streaming_response(
383	                                status,
384	                                &resp_headers,
385	                                upstream_response,
386	                                &request_id,
387	                                state.timeout,
388	                            );
389	                        }
390	                    }
391	
392	                    // Success: stream the response body. This is critical for SSE
393	                    // (Server-Sent Events) from the Anthropic API where Claude
394	                    // responses are streamed in real-time.
395	                    let resp_headers = upstream_response.headers().clone();
396	                    let elapsed = start.elapsed();
397	                    crate::metrics::record_request(
398	                        status.as_u16(),
399	                        &method_str,
400	                        elapsed.as_secs_f64(),
401	                    );
402	                    info!(
403	                        status = status.as_u16(),
404	                        latency_ms = elapsed.as_millis() as u64,
405	                        "request completed"
406	                    );
407	                    return build_streaming_response(
408	                        status,
409	                        &resp_headers,
410	                        upstream_response,
411	                        &request_id,
412	                        state.timeout,
413	                    );
414	                }
415	                Ok(Err(e)) => {
416	                    state
417	                        .errors_total
418	                        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
419	                    let err_status = StatusCode::BAD_GATEWAY;
420	                    crate::metrics::record_request(
421	                        err_status.as_u16(),
422	                        &method_str,
423	                        start.elapsed().as_secs_f64(),
424	                    );
425	                    crate::metrics::record_upstream_error("connection");
426	                    error!(error = %e, "upstream request failed");
427	                    return error_response(
428	                        err_status,
429	                        &format!("upstream error: {e}"),
430	                        &request_id,
431	                    );
432	                }
433	                Err(_elapsed) => {
434	                    if attempt < MAX_UPSTREAM_ATTEMPTS - 1 {
435	                        continue;
436	                    }
437	                    state
438	                        .errors_total
439	                        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
440	                    let err_status = StatusCode::GATEWAY_TIMEOUT;
441	                    crate::metrics::record_request(
442	                        err_status.as_u16(),
443	                        &method_str,
444	                        start.elapsed().as_secs_f64(),
445	                    );
446	                    crate::metrics::record_upstream_error("timeout");
447	                    error!(
448	                        timeout_secs = state.timeout.as_secs(),
449	                        attempts = MAX_UPSTREAM_ATTEMPTS,
450	                        "upstream response timeout after all retries"
451	                    );
452	                    return error_response(
453	                        err_status,
454	                        &format!(
455	                            "upstream response timeout after {}s ({MAX_UPSTREAM_ATTEMPTS} attempts)",
456	                            state.timeout.as_secs()
457	                        ),
458	                        &request_id,
459	                    );
460	                }
461	            }
462	        }
463	
464	        // If we broke out of the timeout loop due to quota exhaustion but have
465	        // more failover attempts, continue to the next account
466	        if last_error_response.is_some() && failover < max_failovers - 1 {
467	            continue;
468	        }
469	
470	        // Last failover attempt exhausted — return the last error response
471	        if let Some((status, resp_headers, error_body)) = last_error_response {
472	            state
473	                .errors_total
474	                .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
475	            crate::metrics::record_request(
476	                status.as_u16(),
477	                &method_str,
478	                start.elapsed().as_secs_f64(),
479	            );
480	            return build_buffered_response(status, &resp_headers, error_body);
481	        }
482	    }
483	
484	    unreachable!("failover loop must return on every code path")
485	}
486	
487	/// Build a response from a buffered error body (used after error classification).
488	fn build_buffered_response(
489	    status: StatusCode,
490	    resp_headers: &reqwest::header::HeaderMap,
491	    body: axum::body::Bytes,
492	) -> Response {
493	    let mut response = Response::builder().status(status);
494	    for (name, value) in resp_headers {
495	        if !is_hop_by_hop(name.as_str()) {
496	            response = response.header(name, value);
497	        }
498	    }
499	    response
500	        .body(axum::body::Body::from(body))
501	        .unwrap_or_else(|e| {
502	            error_response(
503	                StatusCode::INTERNAL_SERVER_ERROR,
504	                &format!("response build error: {e}"),
505	                "",
506	            )
507	        })
508	}
509	
510	/// Build a streaming response (used for success and passthrough error responses).
511	/// Wraps the upstream byte stream with an idle timeout that terminates the stream
512	/// if no data arrives within the given duration.
513	fn build_streaming_response(
514	    status: StatusCode,
515	    resp_headers: &reqwest::header::HeaderMap,
516	    upstream_response: reqwest::Response,
517	    request_id: &str,
518	    idle_timeout: Duration,
519	) -> Response {
520	    let mut response = Response::builder().status(status);
521	    for (name, value) in resp_headers {
522	        if !is_hop_by_hop(name.as_str()) {
523	            response = response.header(name, value);
524	        }
525	    }
526	    let idle_stream = IdleTimeoutStream::new(upstream_response.bytes_stream(), idle_timeout);
527	    response
528	        .body(axum::body::Body::from_stream(idle_stream))
529	        .unwrap_or_else(|e| {
530	            error_response(
531	                StatusCode::INTERNAL_SERVER_ERROR,
532	                &format!("response build error: {e}"),
533	                request_id,
534	            )
535	        })
536	}
537	
538	/// Check if a header is hop-by-hop (should be stripped before forwarding)
539	pub fn is_hop_by_hop(name: &str) -> bool {
540	    HOP_BY_HOP_HEADERS
541	        .iter()
542	        .any(|h| h.eq_ignore_ascii_case(name))
543	}
544	
545	#[cfg(test)]
546	mod tests {
547	    use super::*;
548	
549	    #[test]
550	    fn test_hop_by_hop_detection_all_eight_headers() {
551	        // All 8 spec-defined hop-by-hop headers (RFC 2616 Section 13.5.1)
552	        assert!(is_hop_by_hop("connection"));
553	        assert!(is_hop_by_hop("keep-alive"));
