### Configure OTLP Exporter and Initialize Telemetry in Rust

Source: https://context7.com/open-telemetry/opentelemetry-rust/llms.txt

This snippet demonstrates how to initialize and configure OTLP exporters for traces, metrics, and logs in a Rust application. It sets up global providers and uses them to create instruments for emitting telemetry data. Ensure the `opentelemetry`, `opentelemetry-otlp`, and `opentelemetry-sdk` crates are added as dependencies.

```rust
use opentelemetry::{global, trace::Tracer, KeyValue};
use opentelemetry_otlp::{LogExporter, MetricExporter, SpanExporter};
use opentelemetry_sdk::logs::SdkLoggerProvider;
use opentelemetry_sdk::metrics::SdkMeterProvider;
use opentelemetry_sdk::trace::SdkTracerProvider;
use opentelemetry_sdk::Resource;
use std::error::Error;

fn get_resource() -> Resource {
    Resource::builder()
        .with_service_name("my-production-service")
        .build()
}

fn init_tracer() -> SdkTracerProvider {
    let exporter = SpanExporter::builder()
        // Default: gRPC to http://localhost:4317
        // Use .with_endpoint("http://collector:4317") to customize
        .build()
        .expect("Failed to create span exporter");

    SdkTracerProvider::builder()
        .with_resource(get_resource())
        .with_batch_exporter(exporter) // Batch for production
        .build()
}

fn init_metrics() -> SdkMeterProvider {
    let exporter = MetricExporter::builder()
        .build()
        .expect("Failed to create metric exporter");

    SdkMeterProvider::builder()
        .with_resource(get_resource())
        .with_periodic_exporter(exporter) // Exports every 60s by default
        .build()
}

fn init_logs() -> SdkLoggerProvider {
    let exporter = LogExporter::builder()
        .build()
        .expect("Failed to create log exporter");

    SdkLoggerProvider::builder()
        .with_resource(get_resource())
        .with_batch_exporter(exporter)
        .build()
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    // Initialize all providers
    let tracer_provider = init_tracer();
    let meter_provider = init_metrics();
    let logger_provider = init_logs();

    // Set global providers
    global::set_tracer_provider(tracer_provider.clone());
    global::set_meter_provider(meter_provider.clone());

    // Create instruments
    let tracer = global::tracer("my-service");
    let meter = global::meter("my-service");
    let counter = meter.u64_counter("requests").build();

    // Use OpenTelemetry
    tracer.in_span("main_operation", |_cx| {
        counter.add(1, &[KeyValue::new("status", "success")]);
        // Application logic...
    });

    // Graceful shutdown - flush and close all providers
    tracer_provider.shutdown()?;
    meter_provider.shutdown()?;
    logger_provider.shutdown()?;

    Ok(())
}

```

