### Control Span Properties with OpenTelemetry Special Fields in Rust

Source: https://context7.com/tokio-rs/tracing-opentelemetry/llms.txt

Demonstrates overriding span names, setting span kinds (client/server), and explicitly setting span status (ok/error) using OpenTelemetry-specific fields within tracing spans. Also shows combining these with semantic conventions for HTTP requests.

```rust
use tracing::{info, span};

fn example_special_fields() {
    // Override span name sent to OpenTelemetry
    let span = span!(
        tracing::Level::INFO,
        "static_name",
        otel.name = "dynamic_operation_name",
        user_id = "123"
    );

    // Set span kind
    let client_span = span!(
        tracing::Level::INFO,
        "http_request",
        otel.kind = "client",
        "http.url" = "https://api.example.com/users"
    );

    let server_span = span!(
        tracing::Level::INFO,
        "handle_request",
        otel.kind = "server",
        "http.method" = "POST"
    );

    // Set span status explicitly
    let span_with_status = span!(
        tracing::Level::INFO,
        "operation",
        otel.status_code = "ok"
    );

    // Or indicate error with description
    let error_span = span!(
        tracing::Level::ERROR,
        "failed_operation",
        otel.status_code = "error",
        otel.status_description = "Database connection timeout"
    );

    // Combine with semantic conventions
    let http_span = span!(
        tracing::Level::INFO,
        "http_call",
        otel.kind = "client",
        "http.method" = "GET",
        "http.url" = "https://example.com",
        "http.status_code" = 200,
        "server.address" = "example.com",
        "server.port" = 443
    );
}

